import numpy as np
def equation(t, P, params):
    p = params
    lt = np.log(t)
    return (p[0] + p[1]*t + p[2]*lt + p[3]/t + p[4]*np.sqrt(t)
            + (p[5] + p[6]*t)*P + (p[7] + p[8]*t)*P**2 + p[9]*np.sqrt(P))
